// @ts-check
import { Command } from '../../utils/Command.js'
import { Type } from '../../utils/Type.js'
import { TypeDeserializer } from './TypeDeserializer.js'

/**
 * @typedef {{ buffer: Uint8Array, position: number }} DeserializeState
 */

export class CommandDeserializer {
    constructor() {
        throw new Error('CommandDeserializer is a static utility class and cannot be instantiated')
    }

    /**
     * @param {Uint8Array} byteArray
     * @returns {Command}
     */
    static deserialize(byteArray) {
        /** @type {DeserializeState} */
        const state = {
            buffer: byteArray,
            position: 11,
        }

        const runtimeName = byteArray[0]
        const commandType = byteArray[10]
        const payload = []

        while (state.position < state.buffer.length) {
            payload.push(CommandDeserializer.readObject(state, state.buffer[state.position]))
        }

        return new Command(runtimeName, commandType, payload)
    }

    /**
     * @param {DeserializeState} state
     * @param {number} typeNum
     * @returns {any}
     */
    static readObject(state, typeNum) {
        const entry = Object.entries(Type).find((entry) => entry[1] === typeNum)
        if (!entry) throw new Error('Unknown type number: ' + typeNum)
        const type = entry[0]
        switch (type) {
            case 'HT_COMMAND':
                return CommandDeserializer.readCommand(state)
            case 'HT_STRING':
                return CommandDeserializer.readString(state)
            case 'HT_INTEGER':
                return CommandDeserializer.readInt(state)
            case 'HT_BOOLEAN':
                return CommandDeserializer.readBool(state)
            case 'HT_FLOAT':
                return CommandDeserializer.readFloat(state)
            case 'HT_BYTE':
                return CommandDeserializer.readByte(state)
            case 'HT_CHAR':
                return CommandDeserializer.readChar(state)
            case 'HT_LONG_LONG':
                return CommandDeserializer.readLongLong(state)
            case 'HT_DOUBLE':
                return CommandDeserializer.readDouble(state)
            case 'HT_UNSIGNED_LONG_LONG':
                return CommandDeserializer.readUllong(state)
            case 'HT_UNSIGNED_INTEGER':
                return CommandDeserializer.readUInt(state)
            case 'HT_NULL':
                return CommandDeserializer.readNull(state)
            case 'HT_UNDEFINED':
                return CommandDeserializer.readUndefined(state)
            default:
                throw 'Unknown type - not supported in JavaScript'
        }
    }

    /**
     * @param {DeserializeState} state
     * @returns {Command}
     */
    static readCommand(state) {
        const p = state.position
        const numberOfElementsInPayload = TypeDeserializer.deserializeInt(state.buffer, p + 1)
        const runtime = state.buffer[p + 5]
        const commandType = state.buffer[p + 6]
        state.position += 7

        const payload = new Array(numberOfElementsInPayload)
        for (let i = 0; i < numberOfElementsInPayload; i++) {
            payload[i] = CommandDeserializer.readObject(state, state.buffer[state.position])
        }

        return new Command(runtime, commandType, payload)
    }

    /**
     * @param {DeserializeState} state
     * @returns {string}
     */
    static readString(state) {
        let p = state.position
        const stringEncodingMode = state.buffer[p + 1]
        const size = TypeDeserializer.deserializeInt(state.buffer, p + 2)
        state.position += 6
        p = state.position
        state.position += size
        return TypeDeserializer.deserializeString(stringEncodingMode, state.buffer, p, size)
    }

    /**
     * @param {DeserializeState} state
     * @returns {number}
     */
    static readInt(state) {
        state.position += 2
        const p = state.position
        state.position += 4
        return TypeDeserializer.deserializeInt(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {boolean}
     */
    static readBool(state) {
        state.position += 2
        const p = state.position
        state.position += 1
        return TypeDeserializer.deserializeBool(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {number}
     */
    static readFloat(state) {
        state.position += 2
        const p = state.position
        state.position += 4
        return TypeDeserializer.deserializeFloat(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {number}
     */
    static readByte(state) {
        state.position += 2
        const p = state.position
        state.position += 1
        return TypeDeserializer.deserializeByte(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {number}
     */
    static readChar(state) {
        state.position += 2
        const p = state.position
        state.position += 1
        return TypeDeserializer.deserializeChar(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {bigint}
     */
    static readLongLong(state) {
        state.position += 2
        const p = state.position
        state.position += 8
        return TypeDeserializer.deserializeLongLong(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {number}
     */
    static readDouble(state) {
        state.position += 2
        const p = state.position
        state.position += 8
        return TypeDeserializer.deserializeDouble(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {bigint}
     */
    static readUllong(state) {
        state.position += 2
        const p = state.position
        state.position += 8
        return TypeDeserializer.deserializeULLong(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {number}
     */
    static readUInt(state) {
        state.position += 2
        const p = state.position
        state.position += 4
        return TypeDeserializer.deserializeUInt(state.buffer, p)
    }

    /**
     * @param {DeserializeState} state
     * @returns {null}
     */
    static readNull(state) {
        state.position += 3
        return TypeDeserializer.deserializeNull()
    }

    /**
     * @param {DeserializeState} state
     * @returns {undefined}
     */
    static readUndefined(state) {
        state.position += 3
        return TypeDeserializer.deserializeUndefined()
    }
}
